export const normalizeRegistrationState = (state) => {
  const raw = String(state || DEFAULT_REGISTRATION_STATE).trim();
  const mapped = STATE_CODE_TO_NAME[raw] || raw;
  return NIGERIA_REGISTRATION_LOCATION_DATA[mapped] ? mapped : DEFAULT_REGISTRATION_STATE;
};

export const getRegistrationLocationOptions = (state, lga = "", ward = "") => {
  const normalizedState = normalizeRegistrationState(state);
  const selectedState = NIGERIA_REGISTRATION_LOCATION_DATA[normalizedState];
  const lgaOptions = selectedState ? Object.keys(selectedState.lgas).sort((a, b) => a.localeCompare(b)) : [];
  const wardOptions = lga && selectedState?.lgas[lga] ? Object.keys(selectedState.lgas[lga].wards).sort((a, b) => a.localeCompare(b)) : [];
  const pollingUnits = ward && selectedState?.lgas[lga]?.wards[ward] ? selectedState.lgas[lga].wards[ward] : lga && selectedState?.lgas[lga] ? Object.values(selectedState.lgas[lga].wards).flat() : [];
  return {
    lgas: lgaOptions,
    wards: wardOptions,
    pollingUnits,
  };
};

const normalizeNameForMatch = (value) => String(value || "").trim().toLowerCase().replace(/[^a-z0-9]+/g, " ").replace(/\s+/g, " ").trim();

/**
 * Resolves a human-typed geography name (e.g. "Ibadan North", any casing or
 * hyphenation) to the exact-cased canonical string this dataset's keys use
 * (e.g. "IBADAN NORTH"). The canonical dataset's own casing/hyphenation is
 * inconsistent between entries (e.g. "IBADAN NORTH EAST" has no hyphen, while
 * "IBADAN SOUTH-EAST" does), so an exact-string caller anywhere other than a
 * dropdown populated from this same list -- a script, a differently-cased API
 * call, a future client -- would otherwise be rejected for a real, valid name.
 * Returns "" when nothing matches.
 */
export const resolveCanonicalName = (candidates, rawValue) => {
  const target = normalizeNameForMatch(rawValue);
  if (!target) return "";
  return candidates.find((candidate) => normalizeNameForMatch(candidate) === target) || "";
};
